script:
(function () {
  'use strict';
  // Capital asset pricing model: E(R) = Rf + beta x (Rm - Rf). Any one of the four values can be
  // solved from the other three:
  //   beta = (E(R) - Rf) / (Rm - Rf)           (needs Rm != Rf)
  //   Rm   = Rf + (E(R) - Rf) / beta           (needs beta != 0)
  //   Rf   = (E(R) - beta x Rm) / (1 - beta)   (needs beta != 1)
  // Market risk premium = Rm - Rf; stock risk premium = beta x (Rm - Rf).
  // Checked in Node (capm.test.js): Rf 4%, beta 1.2, Rm 9% -> 10%; Rf 3%, beta 1.5, Rm 10% -> 13.5%;
  // beta 0 -> Rf; beta 1 -> Rm; each inverse solve reproduces the inputs of the forward solve
  // (10% / 4% / 9% -> beta 1.2; 10% / 4% / 1.2 -> Rm 9%; 10% / 1.2 / 9% -> Rf 4%).
  var LABELS = { er: 'Expected return on the stock', beta: 'Beta', rm: 'Expected market return', rf: 'Risk-free rate' };
  var WRAPS = { er: 'cpErWrap', beta: 'cpBetaWrap', rm: 'cpRmWrap', rf: 'cpRfWrap' };
  var OUTPUTS = ['cpMain', 'cpMrp', 'cpSrp', 'cpOutRf', 'cpOutBeta', 'cpOutRm', 'cpOutEr'];
  var SML_BETAS = [0, 0.5, 0.75, 1, 1.25, 1.5, 2];

  // --- calc start
  // v: { er, rf, beta, rm } as decimals (beta plain); returns the full set or null if unsolvable.
  function solveCapm(target, v) {
    var er = v.er, rf = v.rf, beta = v.beta, rm = v.rm;
    if (target === 'er') er = rf + beta * (rm - rf);
    else if (target === 'beta') {
      if (Math.abs(rm - rf) < 1e-12) return null;
      beta = (er - rf) / (rm - rf);
    } else if (target === 'rm') {
      if (Math.abs(beta) < 1e-12) return null;
      rm = rf + (er - rf) / beta;
    } else if (target === 'rf') {
      if (Math.abs(1 - beta) < 1e-12) return null;
      rf = (er - beta * rm) / (1 - beta);
    }
    if (![er, rf, beta, rm].every(isFinite)) return null;
    return { er: er, rf: rf, beta: beta, rm: rm, mrp: rm - rf, srp: beta * (rm - rf) };
  }
  // --- calc end

  function el(id) { return document.getElementById(id); }
  function num(id) {
    var v = parseFloat(el(id).value);
    return isFinite(v) ? v : NaN;
  }
  function fix(x, dp) {
    if (Math.abs(x) < 0.5 * Math.pow(10, -dp)) x = 0;
    return x.toLocaleString('en-US', { minimumFractionDigits: dp, maximumFractionDigits: dp }).replace(/^-/, '−');
  }
  function pct(x) { return fix(x * 100, 2) + '%'; }

  function clear(msg) {
    var error = el('cpError');
    error.hidden = !msg;
    error.textContent = msg;
    OUTPUTS.forEach(function (id) { el(id).textContent = '–'; });
    el('cpSml').innerHTML = '';
  }

  function update() {
    var target = el('cpSolve').value;
    if (!LABELS[target]) target = 'er';
    Object.keys(WRAPS).forEach(function (k) { el(WRAPS[k]).hidden = k === target; });
    el('cpMainLabel').textContent = LABELS[target];

    var v = { er: num('cpEr'), rf: num('cpRf'), beta: num('cpBeta'), rm: num('cpRm') };
    var msg = '';
    if (target !== 'rf' && (isNaN(v.rf) || v.rf < -10 || v.rf > 100)) msg = 'Enter a risk-free rate from -10% to 100%.';
    else if (target !== 'beta' && (isNaN(v.beta) || v.beta < -10 || v.beta > 10)) msg = 'Enter a beta from -10 to 10.';
    else if (target !== 'rm' && (isNaN(v.rm) || v.rm < -100 || v.rm > 100)) msg = 'Enter an expected market return from -100% to 100%.';
    else if (target !== 'er' && (isNaN(v.er) || v.er < -100 || v.er > 100)) msg = 'Enter an expected stock return from -100% to 100%.';
    if (msg) { clear(msg); return; }

    var r = solveCapm(target, { er: v.er / 100, rf: v.rf / 100, beta: v.beta, rm: v.rm / 100 });
    if (!r) {
      clear(target === 'beta' ? 'Beta cannot be solved when the market return equals the risk-free rate.' :
            target === 'rm' ? 'The market return cannot be solved when beta is 0.' :
            'The risk-free rate cannot be solved when beta is exactly 1.');
      return;
    }
    clear('');
    el('cpMain').textContent = target === 'beta' ? fix(r.beta, 3) : pct(r[target]);
    el('cpMrp').textContent = pct(r.mrp);
    el('cpSrp').textContent = pct(r.srp);
    el('cpOutRf').textContent = pct(r.rf);
    el('cpOutBeta').textContent = fix(r.beta, 3);
    el('cpOutRm').textContent = pct(r.rm);
    el('cpOutEr').textContent = pct(r.er);
    var betas = SML_BETAS.slice();
    var rounded = Math.round(r.beta * 1000) / 1000;
    if (betas.indexOf(rounded) === -1) betas.push(rounded);
    betas.sort(function (a, b) { return a - b; });
    el('cpSml').innerHTML = betas.map(function (b) {
      var label = b === rounded ? fix(b, 3).replace(/0$/, '') + ' (yours)' : fix(b, 2);
      return '<tr><td>' + label + '</td><td>' + pct(b * r.mrp) + '</td><td>' + pct(r.rf + b * r.mrp) + '</td></tr>';
    }).join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('cpForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
